//! C++ rendering and publication of scanned driver tables.
//!
//! Every selected input must pass before any output is replaced. Files are
//! staged and individually renamed, with rollback on an ordinary I/O failure;
//! this is not a crash-atomic transaction across architectures. The driver
//! manifest owns membership; generated files are outputs, not configuration.

use crate::{
    drivers::{self, Driver, Purpose},
    image::Arch,
    scan::{self, Scan, Status},
};
use anyhow::{bail, ensure, Context, Result};
use std::{
    fmt::Write as _,
    fs,
    io::Write,
    path::{Path, PathBuf},
};
use tempfile::NamedTempFile;

pub fn row(scan: &Scan, scanned_only: bool) -> Result<String> {
    ensure!(scan.complete(), "cannot emit an incomplete scan");
    let mut out = String::new();
    if scan.arch == Arch::Aarch64 {
        out.push_str(" /* aarch64: found by structure, NOT verified on hardware; the hook uses these rows only with MEMCPY_HOOK_ALLOW_UNVERIFIED_ROWS=1 (hook/README.md, aarch64) */\n");
    }
    for (name, site) in [
        ("h2h", &scan.engine),
        ("buffer_init", &scan.staging),
        ("internal_memcpy", &scan.row_copy),
    ] {
        if site.status != Status::Found {
            writeln!(
                out,
                " /* {name}: {}: {} */",
                site.status.name(),
                site.reason.replace("*/", "* / ")
            )
            .unwrap();
        }
    }
    writeln!(out, " {{\n  .version = \"{}\",", scan.version).unwrap();
    for (name, site) in [
        ("h2h", &scan.engine),
        ("buffer_init", &scan.staging),
        ("internal_memcpy", &scan.row_copy),
    ] {
        writeln!(out, "  .{name}_va = {:#x},", site.offset).unwrap();
        let bytes = site
            .prologue
            .iter()
            .map(|b| format!("0x{b:02x}"))
            .collect::<Vec<_>>()
            .join(",");
        writeln!(out, "  .{name}_prologue = {{{bytes}}},").unwrap();
    }
    for (name, value) in scan.descriptor.fields() {
        writeln!(out, "  .{name} = {value:#x},").unwrap();
    }
    for (name, value) in [
        ("op_kind_1", scan.descriptor.op_kind_1),
        ("op_kind_2", scan.descriptor.op_kind_2),
        ("op_kind_3", scan.descriptor.op_kind_3),
    ] {
        writeln!(out, "  .{name} = {value},").unwrap();
    }
    scan.inline.write_fields(&mut out)?;
    if scanned_only {
        out.push_str("  .scanned_only = true,\n");
    }
    out.push_str(" },\n");
    Ok(out)
}

pub fn render(rows: &[(Scan, bool)]) -> Result<String> {
    let mut out = String::from("/* generated by cmt-sigscan (tools/sigscan) - do not edit */\nconst DriverVersion g_versions[] = {\n");
    for (scan, scanned_only) in rows {
        out.push_str(&row(scan, *scanned_only)?);
    }
    writeln!(out, "}};\nconst int g_versions_count = {};", rows.len()).unwrap();
    Ok(out)
}

pub struct TableUpdate {
    pub path: PathBuf,
    pub original: String,
    pub generated: String,
}

/// The manifest is the only membership list. Generated C++ contributes its
/// handwritten preamble, never the set of versions to scan. Selecting an
/// architecture always regenerates its whole table; there is no version filter
/// that can accidentally delete the unselected rows.
pub fn prepare(
    repo: &Path,
    cache: &Path,
    manifest: &[Driver],
    arch: Option<Arch>,
    explain: bool,
) -> Result<Vec<TableUpdate>> {
    let architectures = arch.map_or_else(|| vec![Arch::X86_64, Arch::Aarch64], |a| vec![a]);
    let mut updates = Vec::new();
    for arch in architectures {
        let path = repo.join("src/gen").join(arch.table_name());
        let original =
            fs::read_to_string(&path).with_context(|| format!("read table {}", path.display()))?;
        let selected: Vec<_> = manifest
            .iter()
            .filter(|d| d.arch == arch && matches!(d.purpose, Purpose::Table | Purpose::Scanned))
            .collect();
        ensure!(
            !selected.is_empty(),
            "manifest has no table entries for {arch}; refusing an empty table"
        );
        let mut rows = Vec::new();
        for driver in selected {
            let input = driver.library(cache);
            drivers::verify_file(&input, &driver.library_sha256).with_context(|| {
                format!(
                    "verify {arch} {}; use 'fetch' for missing inputs",
                    driver.version
                )
            })?;
            let row = scan::file(&input, Some(arch), explain)?;
            ensure!(
                row.version == driver.version,
                "manifest version differs from scanned banner"
            );
            eprintln!(
                "{arch} {}: signatures and descriptor verified",
                driver.version
            );
            rows.push((row, driver.purpose == Purpose::Scanned));
        }
        let start = original
            .find("/* generated by ")
            .context("table has no generated-section marker")?;
        let generated = format!("{}{}", &original[..start], render(&rows)?);
        updates.push(TableUpdate {
            path,
            original,
            generated,
        });
    }
    Ok(updates)
}

pub fn publish(updates: &[TableUpdate]) -> Result<()> {
    // Scan and stage every selected table before replacing any of them. Each
    // rename is atomic. On a later I/O error, restore already-replaced tables.
    let mut staged = Vec::new();
    for update in updates {
        if update.generated == update.original {
            continue;
        }
        let parent = update.path.parent().context("table has no parent")?;
        let mut file = NamedTempFile::new_in(parent)?;
        file.as_file()
            .set_permissions(fs::metadata(&update.path)?.permissions())?;
        file.write_all(update.generated.as_bytes())?;
        file.as_file().sync_all()?;
        staged.push((update, file));
    }
    let mut published: Vec<&TableUpdate> = Vec::new();
    for (update, file) in staged {
        if let Err(error) = file.persist(&update.path) {
            let mut rollback_errors = Vec::new();
            for prior in published.into_iter().rev() {
                let restore = || -> Result<()> {
                    let mut file =
                        NamedTempFile::new_in(prior.path.parent().context("table has no parent")?)?;
                    file.as_file()
                        .set_permissions(fs::metadata(&prior.path)?.permissions())?;
                    file.write_all(prior.original.as_bytes())?;
                    file.as_file().sync_all()?;
                    file.persist(&prior.path).map_err(|e| e.error)?;
                    Ok(())
                };
                if let Err(error) = restore() {
                    rollback_errors.push(format!("{}: {error:#}", prior.path.display()));
                }
            }
            bail!(
                "publish {}: {}; rollback errors: {}",
                update.path.display(),
                error.error,
                rollback_errors.join("; ")
            );
        }
        published.push(update);
    }
    Ok(())
}
